import React, { useEffect, useRef, useState } from 'react';

const ROLES = [
  'Data Science Enthusiast ✨',
  'Web Developer 🌸',
  'Machine Learning Explorer 🤖',
  'Creative Problem Solver 💡',
];

// SVG petal shapes for floating decoration
const Petal = ({ style }) => (
  <svg viewBox="0 0 40 60" style={{ position:'absolute', opacity:0.12, ...style }}>
    <ellipse cx="20" cy="30" rx="15" ry="28" fill="url(#pg)" transform="rotate(-15 20 30)" />
    <defs>
      <linearGradient id="pg" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stopColor="#e8799a"/>
        <stop offset="100%" stopColor="#b882d4"/>
      </linearGradient>
    </defs>
  </svg>
);

const Hero = ({ data }) => {
  const [roleIdx, setRoleIdx]   = useState(0);
  const [displayed, setDisplayed] = useState('');
  const [typing, setTyping]     = useState(true);
  const charRef = useRef(0);

  useEffect(() => {
    const role = ROLES[roleIdx];
    if (typing) {
      if (charRef.current < role.length) {
        const t = setTimeout(() => { setDisplayed(role.slice(0, charRef.current+1)); charRef.current++; }, 60);
        return () => clearTimeout(t);
      } else {
        const t = setTimeout(() => setTyping(false), 2000);
        return () => clearTimeout(t);
      }
    } else {
      if (charRef.current > 0) {
        const t = setTimeout(() => { setDisplayed(role.slice(0, charRef.current-1)); charRef.current--; }, 35);
        return () => clearTimeout(t);
      } else { setRoleIdx(i => (i+1) % ROLES.length); setTyping(true); }
    }
  }, [displayed, typing, roleIdx]);

  return (
    <section style={{
      minHeight:'100vh', display:'flex', alignItems:'center', justifyContent:'center',
      padding:'100px 2rem 60px', position:'relative', overflow:'hidden',
    }}>
      {/* Decorative petals */}
      <Petal style={{ top:'10%', right:'6%', width:120, height:180, transform:'rotate(20deg)', animation:'rotate-slow 25s linear infinite' }} />
      <Petal style={{ bottom:'12%', left:'4%', width:90, height:140, transform:'rotate(-30deg)', animation:'rotate-slow 30s linear infinite reverse' }} />
      <Petal style={{ top:'50%', right:'3%', width:60, height:90, animation:'float 6s ease-in-out infinite' }} />

      {/* Soft glowing orbs */}
      <div style={{
        position:'absolute', top:'20%', left:'10%',
        width:300, height:300, borderRadius:'50%',
        background:'radial-gradient(circle, rgba(184,130,212,0.07) 0%, transparent 70%)',
        pointerEvents:'none',
      }} />
      <div style={{
        position:'absolute', bottom:'20%', right:'10%',
        width:250, height:250, borderRadius:'50%',
        background:'radial-gradient(circle, rgba(232,121,154,0.07) 0%, transparent 70%)',
        pointerEvents:'none',
      }} />

      <div style={{ maxWidth:900, width:'100%', textAlign:'center', position:'relative', zIndex:1 }}>
        {/* Greeting pill */}
        <div style={{
          display:'inline-flex', alignItems:'center', gap:'0.5rem',
          padding:'0.45rem 1.3rem',
          background:'rgba(232,121,154,0.1)',
          border:'1px solid rgba(232,121,154,0.3)',
          borderRadius:'50px', marginBottom:'2rem',
          animation:'fadeUp 0.6s ease forwards',
        }}>
          <span style={{ fontSize:'0.9rem' }}>🌸</span>
          <span style={{ fontSize:'0.82rem', color:'#f2a4bb', letterSpacing:'0.12em', fontFamily:"'DM Mono', monospace" }}>
            Hello, I'm
          </span>
        </div>

        {/* Avatar with floral ring */}
        <div style={{
          position:'relative', display:'inline-block',
          marginBottom:'2rem', animation:'fadeUp 0.6s 0.1s ease both',
        }}>
          {/* Outer floral ring */}
          <svg width="160" height="160" viewBox="0 0 160 160" style={{ position:'absolute', top:-20, left:'50%', marginLeft:-80, animation:'rotate-slow 18s linear infinite', opacity:0.35 }}>
            {[0,45,90,135,180,225,270,315].map((deg,i) => (
              <ellipse key={deg}
                cx={80 + 68*Math.cos((deg-90)*Math.PI/180)}
                cy={80 + 68*Math.sin((deg-90)*Math.PI/180)}
                rx="9" ry="5"
                fill={i % 2 === 0 ? '#e8799a' : '#b882d4'}
                transform={`rotate(${deg} ${80 + 68*Math.cos((deg-90)*Math.PI/180)} ${80 + 68*Math.sin((deg-90)*Math.PI/180)})`}
              />
            ))}
          </svg>

          <div style={{
            width:120, height:120, borderRadius:'50%',
            background:'linear-gradient(135deg, rgba(232,121,154,0.2), rgba(184,130,212,0.2))',
            border:'2px solid rgba(232,121,154,0.45)',
            display:'flex', alignItems:'center', justifyContent:'center',
            margin:'0 auto',
            boxShadow:'0 0 45px rgba(232,121,154,0.25)',
          }}>
            <span style={{
              fontFamily:"'Cormorant Garamond', serif",
              fontSize:'2.5rem', fontWeight:700,
              background:'linear-gradient(135deg, #e8799a, #b882d4)',
              WebkitBackgroundClip:'text', WebkitTextFillColor:'transparent',
            }}>MG</span>
          </div>
        </div>

        {/* Name */}
        <h1 style={{
          fontFamily:"'Cormorant Garamond', serif",
          fontSize:'clamp(2.4rem, 7vw, 4.8rem)',
          fontWeight:700, color:'#fdf0f4', lineHeight:1.1,
          marginBottom:'0.75rem',
          animation:'fadeUp 0.6s 0.2s ease both',
        }}>
          {data?.name || 'Maithily M. Gondode'}
        </h1>

        {/* Typing role */}
        <div style={{
          fontSize:'clamp(0.95rem, 2.3vw, 1.3rem)',
          fontFamily:"'DM Mono', monospace", color:'#e8799a',
          marginBottom:'1.5rem', height:'2.2em',
          display:'flex', alignItems:'center', justifyContent:'center',
          animation:'fadeUp 0.6s 0.3s ease both',
        }}>
          <span style={{ opacity:0.45, marginRight:'0.5rem' }}>{'~'}</span>
          {displayed}
          <span style={{
            display:'inline-block', width:2, height:'1.1em',
            background:'#e8799a', marginLeft:'2px',
            animation:'blink 1s step-end infinite',
          }} />
        </div>

        {/* Bio */}
        <p style={{
          maxWidth:640, margin:'0 auto 2.5rem',
          color:'rgba(253,240,244,0.6)', fontSize:'1rem', lineHeight:1.85,
          animation:'fadeUp 0.6s 0.4s ease both',
        }}>
          {data?.profile}
        </p>

        {/* Contact chips */}
        <div style={{
          display:'flex', flexWrap:'wrap', justifyContent:'center',
          gap:'0.65rem', marginBottom:'2.5rem',
          animation:'fadeUp 0.6s 0.5s ease both',
        }}>
          {[
            { icon:'✉', text: data?.email },
            { icon:'📞', text: data?.phone },
            { icon:'📍', text: data?.location },
          ].map((item,i) => (
            <div key={i} style={{
              display:'flex', alignItems:'center', gap:'0.4rem',
              padding:'0.4rem 1rem',
              background:'rgba(232,121,154,0.06)',
              border:'1px solid rgba(232,121,154,0.15)',
              borderRadius:'50px', fontSize:'0.82rem',
              color:'rgba(253,240,244,0.6)',
            }}>
              <span>{item.icon}</span><span>{item.text}</span>
            </div>
          ))}
        </div>

        {/* CTAs */}
        <div style={{
          display:'flex', flexWrap:'wrap', gap:'1rem', justifyContent:'center',
          animation:'fadeUp 0.6s 0.6s ease both',
        }}>
          <a href="#contact"
            style={{
              padding:'0.9rem 2.2rem',
              background:'linear-gradient(135deg, #e8799a, #b882d4)',
              color:'#fff', fontWeight:700, borderRadius:'50px',
              textDecoration:'none', fontSize:'0.95rem',
              display:'inline-flex', alignItems:'center', gap:'0.5rem',
              boxShadow:'0 4px 28px rgba(232,121,154,0.4)',
              transition:'all 0.3s ease', border:'none', cursor:'pointer',
              fontFamily:"'Nunito', sans-serif",
            }}
            onMouseEnter={e => { e.currentTarget.style.transform='translateY(-3px)'; e.currentTarget.style.boxShadow='0 8px 38px rgba(232,121,154,0.55)'; }}
            onMouseLeave={e => { e.currentTarget.style.transform='translateY(0)'; e.currentTarget.style.boxShadow='0 4px 28px rgba(232,121,154,0.4)'; }}
          >✉ Get In Touch</a>
          <a href="#projects"
            style={{
              padding:'0.9rem 2.2rem',
              background:'transparent', color:'#e8b96a', fontWeight:600,
              borderRadius:'50px', textDecoration:'none', fontSize:'0.95rem',
              display:'inline-flex', alignItems:'center', gap:'0.5rem',
              border:'1.5px solid rgba(232,185,106,0.5)',
              transition:'all 0.3s ease', fontFamily:"'Nunito', sans-serif",
            }}
            onMouseEnter={e => { e.currentTarget.style.background='rgba(232,185,106,0.1)'; e.currentTarget.style.transform='translateY(-3px)'; }}
            onMouseLeave={e => { e.currentTarget.style.background='transparent'; e.currentTarget.style.transform='translateY(0)'; }}
          >🚀 View My Work</a>
        </div>

        {/* Social links */}
        <div style={{
          display:'flex', justifyContent:'center', gap:'1rem', marginTop:'2.5rem',
          animation:'fadeUp 0.6s 0.7s ease both',
        }}>
          {[
            { href:'https://github.com/Maithily27', label:'GitHub', icon:(
              <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor">
                <path d="M12 0C5.37 0 0 5.37 0 12c0 5.31 3.435 9.795 8.205 11.385.6.105.825-.255.825-.57 0-.285-.015-1.23-.015-2.235-3.015.555-3.795-.735-4.035-1.41-.135-.345-.72-1.41-1.23-1.695-.42-.225-1.02-.78-.015-.795.945-.015 1.62.87 1.845 1.23 1.08 1.815 2.805 1.305 3.495.99.105-.78.42-1.305.765-1.605-2.67-.3-5.46-1.335-5.46-5.925 0-1.305.465-2.385 1.23-3.225-.12-.3-.54-1.53.12-3.18 0 0 1.005-.315 3.3 1.23.96-.27 1.98-.405 3-.405s2.04.135 3 .405c2.295-1.56 3.3-1.23 3.3-1.23.66 1.65.24 2.88.12 3.18.765.84 1.23 1.905 1.23 3.225 0 4.605-2.805 5.625-5.475 5.925.435.375.81 1.095.81 2.22 0 1.605-.015 2.895-.015 3.3 0 .315.225.69.825.57A12.02 12.02 0 0 0 24 12c0-6.63-5.37-12-12-12z"/>
              </svg>
            )},
            { href:'https://linkedin.com/in/maithily-gondode', label:'LinkedIn', icon:(
              <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor">
                <path d="M20.447 20.452h-3.554v-5.569c0-1.328-.027-3.037-1.852-3.037-1.853 0-2.136 1.445-2.136 2.939v5.667H9.351V9h3.414v1.561h.046c.477-.9 1.637-1.85 3.37-1.85 3.601 0 4.267 2.37 4.267 5.455v6.286zM5.337 7.433a2.062 2.062 0 0 1-2.063-2.065 2.064 2.064 0 1 1 2.063 2.065zm1.782 13.019H3.555V9h3.564v11.452zM22.225 0H1.771C.792 0 0 .774 0 1.729v20.542C0 23.227.792 24 1.771 24h20.451C23.2 24 24 23.227 24 22.271V1.729C24 .774 23.2 0 22.222 0h.003z"/>
              </svg>
            )},
          ].map(link => (
            <a key={link.label} href={link.href} target="_blank" rel="noopener noreferrer"
              style={{
                width:42, height:42, borderRadius:'50%',
                display:'flex', alignItems:'center', justifyContent:'center',
                background:'rgba(232,121,154,0.08)',
                border:'1px solid rgba(232,121,154,0.2)',
                color:'rgba(253,240,244,0.65)', transition:'all 0.3s ease',
              }}
              onMouseEnter={e => { e.currentTarget.style.background='rgba(232,121,154,0.18)'; e.currentTarget.style.borderColor='rgba(232,121,154,0.5)'; e.currentTarget.style.color='#e8799a'; e.currentTarget.style.transform='translateY(-3px)'; }}
              onMouseLeave={e => { e.currentTarget.style.background='rgba(232,121,154,0.08)'; e.currentTarget.style.borderColor='rgba(232,121,154,0.2)'; e.currentTarget.style.color='rgba(253,240,244,0.65)'; e.currentTarget.style.transform='translateY(0)'; }}
            >{link.icon}</a>
          ))}
        </div>

        {/* Scroll indicator */}
        <div style={{
          marginTop:'4rem', display:'flex', flexDirection:'column',
          alignItems:'center', gap:'0.5rem', opacity:0.45,
          animation:'fadeIn 1s 1.5s ease both',
        }}>
          <span style={{ fontFamily:"'DM Mono', monospace", fontSize:'0.68rem', letterSpacing:'0.18em', color:'#e8799a' }}>SCROLL</span>
          <div style={{ width:1, height:50, background:'linear-gradient(to bottom, #e8799a, transparent)', animation:'float 2s ease-in-out infinite' }} />
        </div>
      </div>

      <style>{`
        @keyframes blink { 0%,100%{opacity:1} 50%{opacity:0} }
        @keyframes rotate-slow { to { transform: rotate(360deg); } }
        @keyframes float { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-12px)} }
        @keyframes fadeUp { from{opacity:0;transform:translateY(30px)} to{opacity:1;transform:translateY(0)} }
        @keyframes fadeIn { from{opacity:0} to{opacity:1} }
      `}</style>
    </section>
  );
};

export default Hero;
